Export.Routine:
updateFilesInNmSp
#include %occInclude
 set usrNm = "lpjnaras"
 read "Enter passwd: ", passWd

 set sysNmSp = $LISTBUILD("%SYS", "DOCBOOK", "ENSEMBLE", "ENSDEMO", "HSCUSTOM", "HSLIB", "HSSYS", "SAMPLES", "USER")
 WRITE !, "START: " _ $NAMESPACE
 try 
 {
		Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CreateListOfFilesInSvn(usrNm, passWd)
		WRITE !, "CreateListOfFilesInSvn complete"
	    Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).UpdateClassesFromAudit()
	    WRITE !, "UpdateClassesFromAudit complete"
 } CATCH ex {
      WRITE !, "CATCH exception: " _ ex _$ZCVT(ex.Name,"O","HTML"),!

  } 
 set $NAMESPACE = "%SYS"
 Write !, $NAMESPACE
 set statement=##class(%SQL.Statement).%New()
 set status=statement.%PrepareClassQuery("%SYS.Namespace","List")
 WRITE !, status
 if $$$ISERR(status) { do $system.OBJ.DisplayError(status) }
 set resultset=statement.%Execute()


 while resultset.%Next() {
	set nmSP(resultset.%GetData(1)) = 1
 }
 set $NAMESPACE = "ITFCOMMON"
 Set key = $Order(nmSP(""))
 While (key '= "") {
	 if ($LISTFIND(sysNmSp, key) > 0)
	 {
		 WRITE !, "SKIP: " _ key
	 }   
	 ELSE
	 {
     	Write !, " GetOtherFiles " _ key
     	try {
	     	Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetOtherFiles(key)
     	} CATCH ex {
      		WRITE !, "CATCH exception in GetOtherFiles: " _ ex _$ZCVT(ex.Name,"O","HTML"),!

  		} 
   		WRITE !, "  " _ key _ " Updated "
	 }
     SET key = $ORDER(nmSP(key))

 }


 WRITE !, "DONE"
